import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const STATUS_TYPES = [
  '품의서·원인행위·결의서 현황',
  '지출결의서 현황',
  '예실 대비 현황',
  '프로젝트별 예산 구성비',
  '예산과목 원장',
  '자금예산서',
  '추가경정자금예산서',
  '자금계산서',
];
const PROGRESS = ['기안', '결재대기', '승인', '보류', '반려', '회수', '재기안', '완료'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const ID_RE = /^\d+$/;
// 가정: 집계 대상 본예산·실행예산·예산조정은 승인된 건만 센다
// 가정: 예산과목 잔액(balance) = 신청금액 + 조정금액 - 결의금액(승인·완료). 조정은 전용·이용 출처 차감, 대상 가산
const ZERO = 'CAST(0 AS numeric)';
const KEYS = ['requisitionAmount', 'commitmentAmount', 'resolutionAmount', 'budgetAmount', 'executionAmount', 'adjustmentAmount', 'ratio', 'balance'];

const range = (a: string) => `${a}.created_at >= CAST(:fromDate AS date) AND ${a}.created_at < CAST(:toDate AS date) + 1`;
const pf = (a: string) => `(CAST(:projectId AS bigint) IS NULL OR ${a}.project_id = CAST(:projectId AS bigint))`;
const af = (a: string) => `(CAST(:budgetAccountId AS bigint) IS NULL OR ${a}.budget_account_id = CAST(:budgetAccountId AS bigint))`;
const ps = (a: string) => `(CAST(:progressStatus AS text) IS NULL OR ${a}.status = CAST(:progressStatus AS text))`;
const fy = (a: string) => `${a}.fiscal_year BETWEEN EXTRACT(YEAR FROM CAST(:fromDate AS date)) AND EXTRACT(YEAR FROM CAST(:toDate AS date))`;

function head(p: string, a: string): string {
  return `${p} AS \"projectId\", ${a} AS \"budgetAccountId\"`;
}

function cols(m: Record<string, string>, status?: string): string {
  const s = status ?? 'CAST(NULL AS text)';
  return `${s} AS \"status\", ` + KEYS.map((k) => `${m[k] ?? ZERO} AS \"${k}\"`).join(', ');
}

const EXEC = `(SELECT COALESCE(SUM(e.execution_amount), 0) FROM budget_execution e JOIN budget_main bm ON bm.budget_main_id = e.budget_main_id WHERE bm.project_id = m.project_id AND bm.budget_account_id = m.budget_account_id AND ${fy('bm')} AND e.approval_status = '승인')`;
const ADJ = `((SELECT COALESCE(SUM(CASE WHEN a.adjustment_type IN ('전용', '이용') THEN -a.adjustment_amount ELSE a.adjustment_amount END), 0) FROM budget_adjustment a WHERE a.project_id = m.project_id AND a.budget_account_id = m.budget_account_id AND a.approval_status = '승인' AND ${range('a')}) + (SELECT COALESCE(SUM(a2.adjustment_amount), 0) FROM budget_adjustment a2 WHERE a2.project_id = m.project_id AND a2.target_budget_account_id = m.budget_account_id AND a2.approval_status = '승인' AND ${range('a2')}))`;
const RES = `(SELECT COALESCE(SUM(x.resolution_amount), 0) FROM expense_resolution x WHERE x.project_id = m.project_id AND x.budget_account_id = m.budget_account_id AND x.status IN ('승인', '완료') AND ${range('x')})`;
const BASE = `FROM (SELECT b.project_id, b.budget_account_id, SUM(b.requested_amount) AS amount FROM budget_main b WHERE ${fy('b')} AND b.approval_status = '승인' AND ${pf('b')} AND ${af('b')} GROUP BY b.project_id, b.budget_account_id) m`;

function detailSql(): string {
  return `SELECT ${head('m.project_id', 'm.budget_account_id')}, ${cols({
    budgetAmount: 'm.amount',
    executionAmount: EXEC,
    adjustmentAmount: ADJ,
    resolutionAmount: RES,
    balance: `m.amount + ${ADJ} - ${RES}`,
  })} ${BASE}`;
}

function basicSql(): string {
  const sums = KEYS.map((k) => `SUM(t.\"${k}\") AS \"${k}\"`).join(', ');
  return `SELECT t.\"projectId\" AS \"projectId\", CAST(NULL AS bigint) AS \"budgetAccountId\", CAST(NULL AS text) AS \"status\", ${sums} FROM (${detailSql()}) t GROUP BY t.\"projectId\"`;
}

function sqlOf(statusType: string, viewForm: string): string {
  switch (statusType) {
    case '품의서·원인행위·결의서 현황':
      return [
        `SELECT ${head('r.project_id', 'r.budget_account_id')}, ${cols({ requisitionAmount: 'r.requisition_amount' }, 'r.status')} FROM requisition r WHERE ${range('r')} AND ${pf('r')} AND ${af('r')} AND ${ps('r')}`,
        `SELECT ${head('c.project_id', 'c.budget_account_id')}, ${cols({ commitmentAmount: 'c.amount' }, 'c.approval_status')} FROM budget_commitment c WHERE ${range('c')} AND ${pf('c')} AND ${af('c')} AND CAST(:progressStatus AS text) IS NULL`,
        `SELECT ${head('x.project_id', 'x.budget_account_id')}, ${cols({ resolutionAmount: 'x.resolution_amount' }, 'x.status')} FROM expense_resolution x WHERE ${range('x')} AND ${pf('x')} AND ${af('x')} AND ${ps('x')}`,
      ].join(' UNION ALL ');
    case '지출결의서 현황':
      return `SELECT ${head('x.project_id', 'x.budget_account_id')}, ${cols({ resolutionAmount: 'x.resolution_amount' }, 'x.status')} FROM expense_resolution x WHERE ${range('x')} AND ${pf('x')} AND ${af('x')} AND ${ps('x')}`;
    case '예실 대비 현황':
      return viewForm === '상세' ? detailSql() : basicSql();
    case '프로젝트별 예산 구성비':
      return `SELECT ${head('m.project_id', 'm.budget_account_id')}, ${cols({
        budgetAmount: 'm.amount',
        ratio: `COALESCE(m.amount * 100 / NULLIF((SELECT SUM(t.requested_amount) FROM budget_main t WHERE t.project_id = m.project_id AND ${fy('t')} AND t.approval_status = '승인'), 0), 0)`,
      })} ${BASE}`;
    case '예산과목 원장':
      return detailSql();
    case '자금예산서':
      return `SELECT ${head('m.project_id', 'm.budget_account_id')}, ${cols({ budgetAmount: 'm.amount' })} ${BASE}`;
    case '추가경정자금예산서':
      return `SELECT ${head('a.project_id', 'a.budget_account_id')}, ${cols({ adjustmentAmount: 'SUM(a.adjustment_amount)' })} FROM budget_adjustment a WHERE a.adjustment_type = '추경예산' AND a.approval_status = '승인' AND ${range('a')} AND ${pf('a')} AND ${af('a')} GROUP BY a.project_id, a.budget_account_id`;
    default:
      return `SELECT ${head('x.project_id', 'x.budget_account_id')}, ${cols({ resolutionAmount: 'SUM(x.resolution_amount)' })} FROM expense_resolution x WHERE x.status IN ('승인', '완료') AND ${range('x')} AND ${pf('x')} AND ${af('x')} GROUP BY x.project_id, x.budget_account_id`;
  }
}

function text(v: unknown): string {
  return typeof v === 'string' ? v.trim() : '';
}

function optionalId(v: unknown, label: string): string | null {
  const s = text(v);
  if (s === '') return null;
  if (!ID_RE.test(s)) {
    throw new ApiError(400, 'VALIDATION_FAILED', `${label} 형식이 올바르지 않습니다.`);
  }
  return s;
}

@Controller('api/v1')
export class FnSfr00502Controller {
  @Get('/budget-status')
  async listBudgetStatus(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const query = checks.queryOf(req.query);
    const statusType = text(query['statusType']);
    if (statusType === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 항목을 선택해 주세요.');
    }
    if (!STATUS_TYPES.includes(statusType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 항목이 올바르지 않습니다.');
    }
    const fromDate = text(query['fromDate']);
    const toDate = text(query['toDate']);
    if (fromDate === '' || toDate === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 기간을 입력해 주세요.');
    }
    if (!DATE_RE.test(fromDate) || !DATE_RE.test(toDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 기간은 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    if (fromDate > toDate) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일이 종료일보다 늦을 수 없습니다.');
    }
    const projectId = optionalId(query['projectId'], '프로젝트');
    const budgetAccountId = optionalId(query['budgetAccountId'], '예산과목');
    const progressStatus = text(query['progressStatus']);
    if (progressStatus !== '' && !PROGRESS.includes(progressStatus)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '진행상태가 올바르지 않습니다.');
    }
    const viewForm = text(query['viewForm']);
    const pageText = text(query['page']);
    const sizeText = text(query['size']);
    if ((pageText !== '' && !ID_RE.test(pageText)) || (sizeText !== '' && !ID_RE.test(sizeText))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호나 크기 형식이 올바르지 않습니다.');
    }
    const page = pageText === '' ? 0 : Number(pageText);
    let size = sizeText === '' ? DEFAULT_SIZE : Number(sizeText);
    if (size < 1) size = DEFAULT_SIZE;
    if (size > MAX_SIZE) size = MAX_SIZE;
    const sql = sqlOf(statusType, viewForm);
    const params = {
      fromDate,
      toDate,
      projectId,
      budgetAccountId,
      progressStatus: progressStatus === '' ? null : progressStatus,
    };
    return transaction(async (db) => {
      const counted = await db.query(`SELECT COUNT(*) AS total FROM (${sql}) t`, params);
      const total = Number(counted[0]['total']);
      const items = await db.query(
        `SELECT * FROM (${sql}) t ORDER BY t.\"projectId\", t.\"budgetAccountId\" LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { ...params, size, offset: page * size },
      );
      return { items, page, size, total };
    });
  }
}

