import { useState } from 'react';
import { Band, Badge, DataTable, DateInput, ErrorText, Field, Filters, LookupSelect, Num, Pager, RefName, Select, call, useData } from '../kit';
import type { Column, Page, PageProps, Row } from '../kit';

const TYPES: [string, string][] = [
  ['품의서·원인행위·결의서 현황', '품의서·원인행위·결의서 현황'],
  ['지출결의서 현황', '지출결의서 현황'],
  ['예실 대비 현황', '예실 대비 현황'],
  ['프로젝트별 예산 구성비', '프로젝트별 예산 구성비'],
  ['예산과목 원장', '예산과목 원장'],
  ['자금예산서', '자금예산서'],
  ['추가경정자금예산서', '추가경정자금예산서'],
  ['자금계산서', '자금계산서'],
];
const PROGRESS: [string, string][] = ['기안', '결재대기', '승인', '보류', '반려', '회수', '재기안', '완료'].map((s) => [s, s]);
const VIEW_FORMS: [string, string][] = [['기본', '기본'], ['상세', '상세']];
const SIZE = 20;

const projectCol: Column = {
  key: 'projectId',
  label: '프로젝트',
  render: (r) => (r.projectId ? <RefName table='project' role='' value={r.projectId} /> : <span>-</span>),
};

function amountOf(r: Row): [string, unknown] {
  if (Number(r.requisitionAmount) > 0) return ['품의서', r.requisitionAmount];
  if (Number(r.commitmentAmount) > 0) return ['원인행위', r.commitmentAmount];
  return ['결의서', r.resolutionAmount];
}

export default function FnSfr00502Page({ role, notify }: PageProps) {
  const [statusType, setStatusType] = useState('');
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [projectId, setProjectId] = useState<number | string>('');
  const [budgetAccountId, setBudgetAccountId] = useState<number | string>('');
  const [progressStatus, setProgressStatus] = useState('');
  const [viewForm, setViewForm] = useState('');
  const [query, setQuery] = useState<Row | null>(null);
  const [page, setPage] = useState(0);
  const [message, setMessage] = useState('');

  const { data, error, loading } = useData<Page | undefined>(
    () => (query ? call<Page>('GET', '/budget-status', role, undefined, { ...query, page, size: SIZE }) : Promise.resolve(undefined)),
    [query, page, role],
  );

  function search() {
    if (statusType === '') {
      setMessage('조회 항목을 선택해 주세요.');
      return;
    }
    if (fromDate === '' || toDate === '') {
      setMessage('조회 기간을 입력해 주세요.');
      return;
    }
    if (fromDate > toDate) {
      setMessage('조회 시작일이 종료일보다 늦을 수 없습니다.');
      return;
    }
    setMessage('');
    setPage(0);
    setQuery({ statusType, fromDate, toDate, projectId, budgetAccountId, progressStatus, viewForm });
    notify('조회했습니다.');
  }

  function reset() {
    setStatusType('');
    setFromDate('');
    setToDate('');
    setProjectId('');
    setBudgetAccountId('');
    setProgressStatus('');
    setViewForm('');
    setMessage('');
    setQuery(null);
    setPage(0);
  }

  const accountCol: Column = {
    key: 'budgetAccountId',
    label: '예산과목',
    render: (r) => (r.budgetAccountId ? <RefName table='budget_account' role={role} value={r.budgetAccountId} /> : <span>전체</span>),
  };
  const pCol: Column = { ...projectCol, render: (r) => (r.projectId ? <RefName table='project' role={role} value={r.projectId} /> : <span>-</span>) };
  const num = (key: string, label: string): Column => ({ key, label, render: (r) => <Num value={r[key]} /> });
  const type = String(query?.statusType ?? '');
  let columns: Column[];
  if (type === '품의서·원인행위·결의서 현황') {
    columns = [
      pCol,
      accountCol,
      { key: 'kind', label: '구분', render: (r) => <span>{amountOf(r)[0]}</span> },
      { key: 'amount', label: '금액', render: (r) => <Num value={amountOf(r)[1]} /> },
      { key: 'status', label: '진행상태', render: (r) => <Badge value={r.status} /> },
    ];
  } else if (type === '지출결의서 현황') {
    columns = [pCol, accountCol, num('resolutionAmount', '결의 금액'), { key: 'status', label: '진행상태', render: (r) => <Badge value={r.status} /> }];
  } else if (type === '예실 대비 현황' || type === '예산과목 원장') {
    columns = [pCol, accountCol, num('budgetAmount', '신청금액'), num('resolutionAmount', '결의 금액'), num('balance', '잔액')];
  } else if (type === '프로젝트별 예산 구성비') {
    columns = [pCol, accountCol, num('budgetAmount', '신청금액'), num('ratio', '구성비(%)')];
  } else if (type === '추가경정자금예산서') {
    columns = [pCol, accountCol, num('adjustmentAmount', '조정 금액')];
  } else if (type === '자금계산서') {
    columns = [pCol, accountCol, num('resolutionAmount', '결의 금액')];
  } else {
    columns = [pCol, accountCol, num('budgetAmount', '신청금액')];
  }

  const emptyText = query ? '조회 조건에 해당하는 데이터가 없습니다.' : '조회 항목과 기간을 입력한 뒤 조회해 주세요.';

  return (
    <div className='doc'>
      <section className='box'>
        <h2>결의서 현황 및 예실 조회</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='조회 항목' required>
            <Select value={statusType} onChange={setStatusType} options={TYPES} placeholder='선택' />
          </Field>
          <Field label='조회 시작일' required>
            <DateInput value={fromDate} onChange={setFromDate} />
          </Field>
          <Field label='조회 종료일' required>
            <DateInput value={toDate} onChange={setToDate} />
          </Field>
          <Field label='프로젝트'>
            <LookupSelect table='project' role={role} value={projectId} onChange={setProjectId} placeholder='전체' />
          </Field>
          <Field label='예산과목'>
            <LookupSelect table='budget_account' role={role} value={budgetAccountId} onChange={setBudgetAccountId} placeholder='전체' />
          </Field>
          <Field label='진행상태'>
            <Select value={progressStatus} onChange={setProgressStatus} options={PROGRESS} placeholder='전체' />
          </Field>
          <Field label='예실 대비 보기'>
            <Select value={viewForm} onChange={setViewForm} options={VIEW_FORMS} placeholder='기본' />
          </Field>
        </Filters>
        {message !== '' && <ErrorText text={message} />}
        {error !== '' && <ErrorText text={error} />}
      </section>
      <section className='box'>
        <h2>{type !== '' ? type : '조회 결과'}</h2>
        <Band total={data?.total} />
        <DataTable columns={columns} rows={data?.items ?? []} empty={loading ? '불러오는 중입니다.' : emptyText} />
        {data && <Pager page={data.page} size={data.size} total={data.total} onPage={setPage} />}
      </section>
    </div>
  );
}
